RANK_FRAME = (RECORDED / "analysis-rank-frame.parquet").read_bytes()
RANK_MEMBER = DatasetRef.from_json(
    json.dumps(load_recorded("analysis-rank-ready.json")["ref"])
).members[0]
CHAIN = (
    recipe(DatasetRef((HELD,)))
    .quotient_of(Spec(OTHER, {}), on={"destination": "place"})
    .rank(by="destination", per="origin", limit=2)
)


def stored_answer(
    *freshness: str | None, manifest: object = None, **members: object
) -> dict[str, Any]:
    """The recorded rank analysis as a stored post answers it: one
    `resolved_roots` entry per freshness, None for an entry that states none,
    and the derived manifest embedded, or `manifest` in its place. `members`
    replaces or adds top-level members."""
    answer = load_recorded("analysis-rank-ready.json")
    del answer["summary"]
    answer["resolved_roots"] = [
        {"spec_id": HELD.spec.spec_id, "content_version": NEWER}
        | ({} if state is None else {"freshness": state})
        for state in freshness
    ]
    answer["manifest"] = (
        load_recorded("analysis-rank-manifest.json") if manifest is None else manifest
    )
    return answer | members


def file_route() -> str:
    member = RANK_MEMBER
    return (
        f"{BASE}/datasets/derived/{member.spec.spec_id}/{member.content_version}"
        f"/files/{member.digest}"
    )


def test_a_stored_recipe_costs_the_post_and_the_file() -> None:
    server = Server(json_response(200, stored_answer("current")), parquet(RANK_FRAME))
    with make(server) as transport:
        data = fetch(transport, CHAIN, latest="stored")
    # The tree goes as it is built, each root as it stands, and DFO resolves
    # the roots to their stored heads.
    assert server.body(0) == {
        "tree": CHAIN.tree(),
        "latest": "stored",
        "include": ["manifest"],
    }
    assert server.calls() == [f"POST {BASE}/datasets/analysis", f"GET {file_route()}"]
    assert server.requests[1].url.query == b""
    assert data.ref == DatasetRef((RANK_MEMBER,))
    assert data.freshness == "current"
    assert len(data) == pq.read_table(io.BytesIO(RANK_FRAME)).num_rows


