def test_a_pending_stored_post_is_posted_again_after_its_retry_after() -> None:
    timeline = Timeline()
    server = Server(
        json_response(
            202, load_recorded("analysis-pending.json")["body"], {"retry-after": "3"}
        ),
        json_response(200, stored_answer("current")),
        parquet(RANK_FRAME),
    )
    with make(server, timeline) as transport:
        data = fetch(transport, CHAIN, latest="stored")
    assert server.calls()[:2] == [f"POST {BASE}/datasets/analysis"] * 2
    assert server.body(0) == server.body(1)
    assert timeline.sleeps == [3.0]
    assert data.freshness == "current"


def test_a_second_stored_read_takes_the_file_from_the_cache() -> None:
    cache = FakeCache()
    server = Server(
        json_response(200, stored_answer("current")),
        parquet(RANK_FRAME),
        json_response(200, stored_answer("pending")),
    )
    with make(server) as transport:
        fetch(transport, CHAIN, latest="stored", cache=cache)
        again = fetch(transport, CHAIN, latest="stored", cache=cache)
    assert [request.method for request in server.requests] == ["POST", "GET", "POST"]
    assert again.from_cache is True
    assert again.freshness == "pending"


def test_a_computed_frame_under_stored_posts_its_bare_root() -> None:
    server = Server(json_response(200, stored_answer("stale")), parquet(RANK_FRAME))
    ref = derived_ref()
    (member,) = ref.members
    with make(server) as transport:
        data = fetch(transport, ref, latest="stored")
    assert server.body(0) == {
        "tree": {
            "spec_id": member.spec.spec_id,
            "content_version": member.content_version,
        },
        "latest": "stored",
        "include": ["manifest"],
    }
    assert server.calls()[1] == f"GET {file_route()}"
    assert data.freshness == "stale"


def test_a_recipe_of_a_computed_frame_is_posted_under_stored() -> None:
    server = Server(json_response(200, stored_answer("current")), parquet(RANK_FRAME))
    chain = recipe(derived_ref()).rank(by="origin")
    with make(server) as transport:
        fetch(transport, chain, latest="stored")
    assert server.body(0)["tree"] == chain.tree()


def test_offline_each_member_reads_its_newest_cached_version_as_stale(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    cache = FakeCache()
    cache.put_bytes(sha256_digest(DATA), DATA)
    cache.put_manifest(
        HELD.spec.spec_id, NEWER, HELD.rendering, manifest_of(HELD.spec.spec_id)
    )
    monkeypatch.setenv("DFO_OFFLINE", "1")
    server = Server()
    with make(server) as transport:
        data = fetch(transport, DatasetRef((HELD,)), latest="stored", cache=cache)
    assert server.requests == []
    assert data.stale is True
    assert data.freshness is None
    (member,) = data.members
    assert member.content_version == NEWER


