def test_a_deadline_on_the_first_get_is_a_plain_read_timeout() -> None:
    timeline = Timeline()
    server = Server(httpx2.ReadTimeout("slow"))

    def handler(request: httpx2.Request) -> httpx2.Response:
        timeline.now += 5.0
        return server(request)

    with make(handler, timeline) as transport:
        with pytest.raises(DfoTimeoutError) as raised:
            fetch(transport, DatasetRef((HELD,)), latest="stored", timeout=5.0)
    assert raised.value.code == "deadline_exceeded"
    assert "still running" not in str(raised.value)


def test_a_deadline_while_polling_says_the_build_is_still_running() -> None:
    timeline = Timeline()
    server = Server(
        json_response(202, operation("running"), {"retry-after": "2"}),
        json_response(200, operation("running")),
    )
    with make(server, timeline) as transport:
        with pytest.raises(DfoTimeoutError) as raised:
            fetch(transport, DatasetRef((HELD,)), latest="stored", timeout=1.0)
    assert raised.value.code == "deadline_exceeded"
    assert "still running" in str(raised.value)


